import {
  existsSync,
  readdirSync,
  readFileSync,
  renameSync,
  rmSync,
  statSync,
  watch,
  writeFileSync,
} from "node:fs";
import { randomUUID } from "node:crypto";
import * as path from "node:path";
import { pathToFileURL } from "node:url";
import { type CompletedConfig, ts } from "ts-json-schema-generator";
import createSchemaGenerator from "./schema/createGenerator.ts";

export const schemaComment =
  "DO NOT EDIT THIS FILE.  It is generated automatically " +
  "from typescript interfaces in the project.  To update, run " +
  "`bun run schema` (with optional `--watch`).";

export interface SchemaFlags {
  check: boolean;
  watch: boolean;
  force: boolean;
  verbose: boolean;
  help: boolean;
  files: string[];
}

export function parseSchemaArgs(args: string[]): SchemaFlags {
  const flags: SchemaFlags = {
    check: false,
    watch: false,
    force: false,
    verbose: false,
    help: false,
    files: [],
  };
  const aliases: Record<string, keyof Omit<SchemaFlags, "files">> = {
    c: "check",
    w: "watch",
    f: "force",
    v: "verbose",
    h: "help",
  };
  let positional = false;
  for (const arg of args) {
    if (arg === "--" && !positional) {
      positional = true;
      continue;
    }
    if (positional || !arg.startsWith("-")) {
      flags.files.push(arg);
      continue;
    }
    const negative = arg.startsWith("--no-");
    const name = arg.startsWith("--")
      ? arg.slice(negative ? 5 : 2)
      : aliases[arg.slice(1)];
    if (!name || !Object.hasOwn(flags, name) || name === "files") {
      throw new Error(`Unknown option: ${arg}`);
    }
    flags[name as keyof Omit<SchemaFlags, "files">] = !negative;
  }
  if (flags.check && flags.watch) {
    throw new Error("--check cannot be combined with --watch");
  }
  return flags;
}

export function findSchemaSources(directory: string): string[] {
  return readdirSync(directory, { withFileTypes: true }).sort((a, b) =>
    a.name.localeCompare(b.name)
  )
    .flatMap((entry) => {
      const file = path.join(directory, entry.name);
      if (entry.isDirectory()) return findSchemaSources(file);
      if (!entry.isFile() || !file.endsWith(".ts")) return [];
      return /@yf-schema/.test(readFileSync(file, "utf8")) ? [file] : [];
    });
}

function findSchemaOutputs(directory: string): string[] {
  return readdirSync(directory, { withFileTypes: true }).flatMap((entry) => {
    const file = path.join(directory, entry.name);
    if (entry.isDirectory()) return findSchemaOutputs(file);
    return entry.isFile() && file.endsWith(".schema.json") ? [file] : [];
  }).sort();
}

function compilerOptions(configFile: string): ts.CompilerOptions {
  const loaded = ts.readConfigFile(configFile, ts.sys.readFile);
  if (loaded.error) throw new Error(formatDiagnostics([loaded.error]));
  const parsed = ts.parseJsonConfigFileContent(
    loaded.config,
    ts.sys,
    path.dirname(configFile),
  );
  // The generator supplies its own roots, so an empty config include is valid.
  const errors = parsed.errors.filter((error) => error.code !== 18003);
  if (errors.length) throw new Error(formatDiagnostics(errors));
  return { ...parsed.options, noEmit: true };
}

function formatDiagnostics(diagnostics: readonly ts.Diagnostic[]): string {
  return ts.formatDiagnosticsWithColorAndContext(diagnostics, {
    getCanonicalFileName: (file) => file,
    getCurrentDirectory: () => process.cwd(),
    getNewLine: () => "\n",
  });
}

/** Compile without creating the placeholder JSON files used by the old CLI. */
export function generateSchema(
  input: string,
  configFile: string,
  generatedOutputs: ReadonlySet<string> = new Set([
    input.replace(/\.ts$/, ".schema.json"),
  ]),
): string {
  const options = compilerOptions(configFile);
  const host = ts.createCompilerHost(options);
  const read = host.readFile.bind(host);
  const exists = host.fileExists.bind(host);
  const outputs = new Set(
    [...generatedOutputs].map((file) => path.resolve(file)),
  );
  const overlays = new Map<string, boolean>();
  const virtual = (file: string) => {
    const resolved = path.resolve(file);
    if (!outputs.has(resolved)) return false;
    if (!overlays.has(resolved)) {
      let placeholder = !exists(file);
      if (!placeholder) {
        try {
          JSON.parse(read(file)!);
        } catch (error) {
          if (!(error instanceof SyntaxError)) throw error;
          placeholder = true;
        }
      }
      overlays.set(resolved, placeholder);
    }
    return overlays.get(resolved)!;
  };
  host.fileExists = (file) => virtual(file) || exists(file);
  host.readFile = (file) => virtual(file) ? "{}" : read(file);
  const program = ts.createProgram([input], options, host);
  const diagnostics = ts.getPreEmitDiagnostics(program);
  if (diagnostics.length) throw new Error(formatDiagnostics(diagnostics));
  const config = {
    path: input,
    type: "*",
    discriminatorType: "open-api",
    additionalProperties: false,
    jsDoc: "basic",
    expose: "export",
    topRef: true,
  } as CompletedConfig;
  const schema = createSchemaGenerator(program, config).createSchema(
    config.type,
  );
  return JSON.stringify(
    { $schema: schema.$schema, $comment: schemaComment, ...schema },
    null,
    2,
  );
}

export interface SchemaRunOptions {
  root?: string;
  log?: (message: string) => void;
}

/** Full regeneration is intentional: mtimes do not track imported type changes. */
export function runSchemas(
  flags: SchemaFlags,
  options: SchemaRunOptions = {},
): number {
  const root = path.resolve(options.root ?? process.cwd());
  const log = options.log ?? console.log;
  const discovered = findSchemaSources(path.join(root, "src"));
  if (!flags.files.length) {
    const orphans = findSchemaOutputs(path.join(root, "src")).filter((output) =>
      !discovered.includes(output.replace(/\.schema\.json$/, ".ts"))
    );
    if (orphans.length || !discovered.length) {
      for (const output of orphans) {
        log(
          `* ${
            path.relative(root, output)
          }: orphan output; restore its marked source or remove the obsolete schema.`,
        );
      }
      if (!discovered.length) log("No @yf-schema sources found in src.");
      return 1;
    }
  }
  const selected = flags.files.length
    ? flags.files.map((file) => path.resolve(root, file))
    : discovered;
  const sources = [...new Set(selected)].sort();
  const generatedOutputs = new Set(
    [...discovered, ...sources].map((file) =>
      file.replace(/\.ts$/, ".schema.json")
    ),
  );
  const changes: { output: string; content: string }[] = [];
  let failed = false;
  for (const file of sources) {
    try {
      if (!file.endsWith(".ts")) {
        throw new Error(`Expected a .ts source: ${file}`);
      }
      if (!/@yf-schema/.test(readFileSync(file, "utf8"))) {
        log(`* ${path.relative(root, file)}: no @yf-schema marker; skipped.`);
        continue;
      }
      const output = file.replace(/\.ts$/, ".schema.json");
      const content = generateSchema(
        file,
        path.join(root, "scripts/schema-tsconfig.json"),
        generatedOutputs,
      );
      if (!existsSync(output) || readFileSync(output, "utf8") !== content) {
        changes.push({ output, content });
        log(
          `* ${path.relative(root, output)}: ${
            flags.check ? "stale or missing" : "generated"
          }.`,
        );
      } else if (flags.verbose) {
        log(`* ${path.relative(root, output)}: unchanged.`);
      }
    } catch (error) {
      failed = true;
      log(
        `* ${path.relative(root, file)}: ${
          error instanceof Error ? error.message : String(error)
        }`,
      );
    }
  }
  // No writes at all when any generation failed, or during a check.
  if (failed || flags.check) return failed || changes.length > 0 ? 1 : 0;
  const staged: { temporary: string; output: string }[] = [];
  try {
    for (const { output, content } of changes) {
      const temporary = `${output}.${randomUUID()}.tmp`;
      staged.push({ temporary, output });
      writeFileSync(temporary, content, {
        flag: "wx",
        mode: existsSync(output) ? statSync(output).mode & 0o777 : 0o644,
      });
    }
    for (const { temporary, output } of staged) renameSync(temporary, output);
  } catch (error) {
    log(
      `Schema write failed: ${
        error instanceof Error ? error.message : String(error)
      }`,
    );
    return 1;
  } finally {
    for (const { temporary } of staged) rmSync(temporary, { force: true });
  }
  return 0;
}

/** Debounce bursts; changes received during an asynchronous run trigger another run. */
export function createSchemaScheduler(
  run: () => Promise<void>,
  delay = 1000,
  onError: (error: unknown) => void = console.error,
) {
  let timer: ReturnType<typeof setTimeout> | undefined;
  let running = false;
  let dirty = false;
  let closed = false;
  async function drain() {
    if (closed || running || !dirty) return;
    running = true;
    dirty = false;
    try {
      await run();
    } catch (error) {
      onError(error);
    } finally {
      running = false;
      if (dirty && !closed) schedule();
    }
  }
  function schedule() {
    if (closed) return;
    dirty = true;
    clearTimeout(timer);
    timer = setTimeout(() => {
      void drain();
    }, delay);
  }
  return {
    schedule,
    close() {
      closed = true;
      clearTimeout(timer);
    },
  };
}

export const schemaUsage = `Usage: bun run schema [options] [files...]
  -h, --help     Show this help
  -c, --check    Compare full regeneration without writing files
  -w, --watch    Regenerate on source/config changes until interrupted
  -f, --force    Accepted for compatibility; every run checks imported types
  -v, --verbose Report unchanged files too
Explicit paths always regenerate. Unchanged outputs retain their timestamps.
`;

export function schemaMain(
  args: string[],
  options: SchemaRunOptions = {},
): number {
  const log = options.log ?? console.log;
  let flags: SchemaFlags;
  try {
    flags = parseSchemaArgs(args);
  } catch (error) {
    log(String(error));
    return 2;
  }
  if (flags.help) {
    log(schemaUsage);
    return 0;
  }
  try {
    if (!flags.watch) return runSchemas(flags, options);
    const root = path.resolve(options.root ?? process.cwd());
    // Open watchers before initial generation, so startup edits are not lost.
    const scheduler = createSchemaScheduler(
      async () => {
        const code = runSchemas(flags, options);
        log(
          code
            ? "Schema generation failed; still watching."
            : "Schema scan complete; watching.",
        );
      },
      1000,
      (error) =>
        log(`Schema generation failed; still watching: ${String(error)}`),
    );
    const watchers: ReturnType<typeof watch>[] = [];
    let stopped = false;
    const stop = () => {
      if (stopped) return;
      stopped = true;
      scheduler.close();
      for (const watcher of watchers) watcher.close();
      process.off("SIGINT", stop);
      process.off("SIGTERM", stop);
    };
    const onError = (error: Error) => {
      log(`Schema watcher failed: ${error.message}`);
      process.exitCode = 1;
      stop();
    };
    try {
      // Imported types and config edits can live outside src. Ignore
      // package/cache/output churn, including our own generated schema writes.
      const directories = new Set([
        root,
        ...flags.files.map((file) => path.dirname(path.resolve(root, file))),
      ]);
      for (const directory of directories) {
        watchers.push(watch(directory, { recursive: true }, (_event, name) => {
          const file = name?.toString();
          if (
            !file ||
            !/(?:^|[/\\])(?:node_modules|\.git|\.migration-results|tests[/\\]fixtures)(?:[/\\]|$)/
                .test(file) &&
              /\.(?:ts|json)$/.test(file) && !file.endsWith(".schema.json")
          ) scheduler.schedule();
        }));
      }
      for (const watcher of watchers) watcher.on("error", onError);
      process.on("SIGINT", stop);
      process.on("SIGTERM", stop);
      scheduler.schedule();
      log("Watching schema sources and config (Ctrl-C to exit)...");
    } catch (error) {
      stop();
      throw error;
    }
    return 0;
  } catch (error) {
    log(String(error));
    return 1;
  }
}

if (
  process.argv[1] &&
  import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href
) {
  process.exitCode = schemaMain(process.argv.slice(2));
}
